import pathlib,json,gzip,statistics,re,html
from PIL import Image,ImageDraw
root=pathlib.Path('docs/mission-12-evidence/architecture')
before=json.loads((root/'before.json').read_text());after=json.loads((root/'after.json').read_text());perf=json.loads(gzip.decompress((root/'performance.json.gz').read_bytes()))
catalog=json.loads(pathlib.Path('public/materials/architecture/catalog.json').read_text())
titles={'rue':'La rue et ses maisons','facade':'Matières et ouvertures','toitures':'Une série de toitures','village':'Le village depuis la vallée','chateau':'Les ruines, toujours illustratives','aerienne':'Le village en vue aérienne','matin':'La lumière du matin','pluie':'La lumière sous la pluie'}
metrics=[]
for profile in ['eco','balanced','quality']:
 for station in ['rue','facade','toitures','chateau']:
  rows={phase:[r for r in perf['rows'] if r['profile']==profile and r['station']==station and r['phase']==phase] for phase in ['before','after']}
  med={phase:statistics.median(x['ms'] for r in rows[phase] for x in r['samples']) for phase in rows}
  a,b=[rows[k][-1] for k in ['before','after']];assert a['samples'][0]['calls']==b['samples'][0]['calls'];assert a['samples'][0]['triangles']==b['samples'][0]['triangles']
  metrics.append({'profile':profile,'station':station,'beforeMs':med['before'],'afterMs':med['after'],'changePercent':(med['after']/med['before']-1)*100,'calls':b['samples'][0]['calls'],'triangles':b['samples'][0]['triangles'],'texturesBefore':a['state']['textures'],'texturesAfter':b['state']['textures'],'geometryBytesBefore':a['state'].get('heapBytes'),'geometryBytesAfter':b['state'].get('heapBytes')})
summary={'base':'bb58c30601e98ca29f3ffaa020554951bfd37ed6','environment':perf['environment'],'rows':metrics,'atlasBytes':catalog['bytes'],'atlasDimensions':[864,576],'textureGpuEstimateAddedBytes':(864*576-3*128*128)*4*4/3,'interpretation':'Synchronous SwiftShader render/readback times, not hardware GPU FPS. JavaScript heap snapshots are retained in the raw trace and do not measure GPU buffers or prove a leak.'}
# Heap values must not be mislabeled as geometry memory.
for row in metrics:row.pop('geometryBytesBefore');row.pop('geometryBytesAfter')
(root/'summary.json').write_text(json.dumps(summary,ensure_ascii=False,indent=2)+'\n')
cards=[]
for a,b in zip(before['results'],after['results']):
 assert a['station']==b['station'] and a['state']['matrix']==b['state']['matrix'] and a['state']['climate']['date']==b['state']['climate']['date']
 name=a['id'];title=titles[name]
 if name not in ['matin','pluie']:
  board=Image.new('RGB',(1920,680),'#101c19');d=ImageDraw.Draw(board)
  for i,(phase,label) in enumerate([('before','Jalon A · avant'),('after','Jalon B · après')]):d.text((20+i*960,12),label,fill='#e7e2cc');board.paste(Image.open(root/f'{phase}-{name}.jpg'),(i*960,40))
  board.save(root/f'compare-{name}.jpg',quality=88,optimize=True)
 group='conditions' if name in ['matin','pluie'] else 'facades' if name in ['rue','facade'] else 'ensemble'
 cards.append(f'<article class="card" data-family="{group}"><h2>{title}</h2><p class="condition">Équilibré · 960 × 640 · {a["state"]["climate"]["date"]}</p><div class="pair">'+''.join(f'<figure><a href="{phase}-{name}.jpg" target="_blank"><img loading="lazy" src="{phase}-{name}.jpg" alt="{html.escape(title)} — {label}"></a><figcaption>{label}</figcaption></figure>' for phase,label in [('before','Avant · Jalon A'),('after','Après · Jalon B')])+f'</div><details><summary>Caméra de comparaison</summary><code>{html.escape(str(a["station"][1:]))}</code><p>Mêmes matrice, altitude source, heure, météo et profil. Une station photographique ne prouve pas l’accès piéton sur le terrain réel.</p></details></article>')
table=''.join(f'<tr><th>{r["profile"]}</th><td>{titles[r["station"]]}</td><td>{r["beforeMs"]:.1f}</td><td>{r["afterMs"]:.1f}</td><td>{r["changePercent"]:+.1f} %</td><td>{r["calls"]} / {r["triangles"]:,}</td></tr>' for r in metrics)
css=re.search(r'<style>.*?</style>',pathlib.Path('docs/mission-12-evidence/index.html').read_text(),re.S).group()
page='''<!doctype html><html lang="fr"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Endless Earth — Mission 12B</title>'''+css+'''<header><div class="eyebrow">Endless Earth · Mission 12 · Jalon B</div><h1>La matière des maisons,<br>le caractère du village.</h1><p>Pierre et enduit, toitures, bois peint, encadrements et ruines. Des interprétations régionales stables, sur les mêmes emprises et les mêmes hauteurs.</p><span class="tag">Revue artistique attendue · C et D non commencés</span><p class="links"><a href="../../mission-12.md">Rapport et procédure de test</a><a href="../index.html">Revoir le Jalon A</a><a href="/endless-earth/?moment=afternoon&weather=clear">Jeu local</a></p></header><main><section><h2>Huit vues à conditions identiques</h2><p>À gauche : Jalon A livré, commit bb58c30. À droite : Jalon B. Les 921 bâtiments ont des matériaux inconnus dans l’extrait OSM ; les matières et ouvertures proposées restent des interprétations régionales, jamais une reproduction certifiée de chaque habitation.</p><nav aria-label="Filtrer les vues"><button data-filter="all" aria-pressed="true">Tout voir</button><button data-filter="facades" aria-pressed="false">Façades</button><button data-filter="ensemble" aria-pressed="false">Village et patrimoine</button><button data-filter="conditions" aria-pressed="false">Lumière et pluie</button></nav>'''+''.join(cards)+'''</section><section><h2>Dans une vraie promenade</h2><p>Canvas WebGL et son réel du moteur, sans accélération ni normalisation du volume. L’extrait avant reprend le film livré au Jalon A ; le nouveau film suit les mêmes commandes et voies, avec les collisions ordinaires. Ils ne sont pas synchronisés image par image.</p><div class="video-grid"><figure><video controls preload="metadata" src="../after-promenade.webm"></video><figcaption>Jalon A · avant</figcaption></figure><figure><video controls preload="metadata" src="after-promenade.webm"></video><figcaption>Jalon B · après</figcaption></figure></div></section><section><h2>Le coût, mesuré</h2><p>288 rendus, 144 paires, quatre vues, trois profils, trois passages, ordre alterné. Millisecondes médianes avec synchronisation/readback sous SwiftShader : <strong>ce ne sont pas des FPS sur GPU physique</strong>.</p><div class="table"><table><thead><tr><th>Profil</th><th>Station</th><th>Avant ms</th><th>Après ms</th><th>Écart</th><th>Appels / triangles identiques</th></tr></thead><tbody>'''+table+'''</tbody></table></div><p>Un atlas partagé remplace les trois petites textures précédentes : 9 → 7 textures dans les scènes mesurées. PNG : 1,19 Mo ; stockage GPU supplémentaire estimé : 2,28 Mio avec mipmaps. Les attributs de matériau et les UV des ouvertures augmentent aussi les buffers : les comptes détaillés restent dans le rapport. GPU physique et Android restent à valider.</p><p><a href="summary.json">Synthèse</a> · <a href="performance.json.gz">Mesures complètes compressées</a> · <a href="runtime.json">Streaming et secours</a></p></section><section><h2>Une bibliothèque sobre et réutilisable</h2><p>Les matières sont originales et préparées hors ligne : pierre, enduit, tuiles, ardoise quand elle est renseignée, bois peint et matière secondaire générique. Aucun appel à une bibliothèque externe pendant la promenade. Budget : 0 €.</p><p>Les couleurs, échelles, variations, détails et distances LOD appartiennent à la configuration régionale. La graine géométrique antérieure reste séparée de l’apparence : les bâtiments conservent leurs hauteurs, leurs ouvertures principales et leurs empreintes.</p><p><a href="/endless-earth/materials/architecture/catalog.json">Catalogue et empreintes</a> · <a href="preservation.json">Préservation des sources et dimensions</a></p></section><section class="note"><h2>À apprécier ensemble</h2><p>Le caractère de la rue, la répétition des pierres et tuiles, les couleurs, la patine et la lisibilité des ouvertures demandent votre évaluation. Les ruines gardent leurs hauteurs illustratives ; aucune tour ni reconstruction historique n’est ajoutée. Le relief à 10 m et certaines maisons sur pente restent des limites visibles.</p><p>Arrêt au Jalon B. La PR reste en brouillon, sans fusion ni déploiement public. Votre accord explicite est attendu avant C.</p></section><footer>IGN / ASP · Licence Ouverte 2.0 · © OpenStreetMap contributors · ODbL. Matières architecturales originales Endless Earth. Captures du vrai moteur ; aucune illustration générée.</footer></main><script>document.querySelectorAll('[data-filter]').forEach(b=>b.addEventListener('click',()=>{document.querySelectorAll('[data-filter]').forEach(x=>x.setAttribute('aria-pressed',String(x===b)));document.querySelectorAll('[data-family]').forEach(c=>c.hidden=b.dataset.filter!=='all'&&c.dataset.family!==b.dataset.filter)}));</script></html>'''
(root/'index.html').write_text(page)
print(json.dumps(summary,ensure_ascii=False))
